BEGIN TRANSACTION;
CREATE TABLE "changeover_matrix" (
"from_family" TEXT,
  "to_family" TEXT,
  "changeover_minutes" INTEGER
);
CREATE TABLE "eligible_machines" (
"routing_operation_id" TEXT,
  "machine_id" TEXT
);
CREATE TABLE "event_history" (
"event_type" TEXT,
  "entity_id" TEXT,
  "event_time" TEXT,
  "detail" TEXT
);
CREATE TABLE "ground_truth" (
"scenario_id" TEXT,
  "scenario" TEXT,
  "expected_detection" TEXT,
  "description" TEXT
);
CREATE TABLE "inventory_lots" (
"lot_id" TEXT,
  "material_id" TEXT,
  "quantity_on_hand" INTEGER,
  "available_at" TEXT,
  "expiry_date" TEXT
);
CREATE TABLE "machine_calendars" (
"calendar_id" TEXT,
  "machine_id" TEXT,
  "work_date" TEXT,
  "shift" TEXT,
  "shift_start" TEXT,
  "shift_end" TEXT,
  "capacity_minutes" INTEGER,
  "labor_group" TEXT,
  "labor_capacity" INTEGER
);
CREATE TABLE "machine_downtime" (
"downtime_id" TEXT,
  "machine_id" TEXT,
  "downtime_start" TEXT,
  "downtime_end" TEXT,
  "reason" TEXT
);
CREATE TABLE "machines" (
"machine_id" TEXT,
  "machine_name" TEXT,
  "machine_type" TEXT,
  "capacity_units_per_hour" INTEGER,
  "labor_group" TEXT,
  "lifecycle_state" TEXT
);
CREATE TABLE "material_requirements" (
"requirement_id" TEXT,
  "operation_id" TEXT,
  "material_id" TEXT,
  "required_quantity" REAL
);
CREATE TABLE "materials" (
"material_id" TEXT,
  "material_name" TEXT,
  "unit" TEXT,
  "lifecycle_state" TEXT
);
CREATE TABLE "operation_schedule" (
"schedule_id" TEXT,
  "operation_id" TEXT,
  "order_id" TEXT,
  "machine_id" TEXT,
  "labor_group" TEXT,
  "required_labor" INTEGER,
  "tool_ids" TEXT,
  "tool_quantity_required" INTEGER,
  "sequence" INTEGER,
  "operation_type" TEXT,
  "priority" TEXT,
  "due_date" TEXT,
  "setup_start" TEXT,
  "operation_start" TEXT,
  "operation_finish" TEXT,
  "duration_minutes" REAL,
  "changeover_minutes" INTEGER,
  "schedule_status" TEXT
);
CREATE TABLE "operation_tool_requirements" (
"tool_requirement_id" TEXT,
  "operation_id" TEXT,
  "tool_id" TEXT,
  "required_quantity" INTEGER
);
CREATE TABLE "operations" (
"operation_id" TEXT,
  "order_id" TEXT,
  "routing_operation_id" TEXT,
  "sequence" INTEGER,
  "operation_type" TEXT,
  "duration_minutes" INTEGER,
  "required_labor" INTEGER,
  "status" TEXT
);
CREATE TABLE "production_orders" (
"order_id" TEXT,
  "product_id" TEXT,
  "routing_id" TEXT,
  "quantity" INTEGER,
  "order_date" TEXT,
  "due_date" TEXT,
  "priority" TEXT,
  "lifecycle_state" TEXT
);
CREATE TABLE "products" (
"product_id" TEXT,
  "sku" TEXT,
  "product_name" TEXT,
  "family" TEXT,
  "lifecycle_state" TEXT
);
CREATE TABLE "routing_operations" (
"routing_operation_id" TEXT,
  "routing_id" TEXT,
  "sequence" INTEGER,
  "operation_type" TEXT,
  "standard_duration_minutes" INTEGER,
  "required_labor" INTEGER
);
CREATE TABLE "routings" (
"routing_id" TEXT,
  "product_id" TEXT,
  "revision" INTEGER,
  "effective_from" TEXT,
  "effective_to" REAL,
  "lifecycle_state" TEXT
);
CREATE TABLE "scheduling_exceptions" (
"operation_id" TEXT,
  "order_id" TEXT,
  "exception" TEXT
);
CREATE TABLE "tools" (
"tool_id" TEXT,
  "tool_name" TEXT,
  "tool_type" TEXT,
  "quantity_available" INTEGER,
  "lifecycle_state" TEXT
);
COMMIT;